	@Test
	void nonCanonicalGroupKeyPayloadIsChargedUntilParallelMergeCompletes() {
		LmdbNativeRowDetachmentTest.FakeStoreSource values = new LmdbNativeRowDetachmentTest.FakeStoreSource();
		List<Value> terms = new ArrayList<>(64);
		long[] ids = new long[64];
		for (int i = 0; i < ids.length; i++) {
			Value term = SimpleValueFactory.getInstance().createLiteral("group-" + i + "-" + "x".repeat(16_384));
			terms.add(term);
			ids[i] = values.add(term);
		}
		SyntheticValueSource source = new SyntheticValueSource(new DuplicateTermSource(values), PlanValueCatalog.EMPTY)
				.forEvaluation();
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(16L << 20, 16L << 20);
		LmdbNativeHashJoin.queryMemoryOverride = manager;
		ExecutorService workers = Executors.newFixedThreadPool(2);
		ConcurrentMap<Thread, AtomicInteger> factoryCalls = new ConcurrentHashMap<>();
		AtomicLong retainedAtSecondSegment = new AtomicLong(-1L);
		CyclicBarrier secondSegment = new CyclicBarrier(2,
				() -> retainedAtSecondSegment.set(manager.usedBytes()));
		try {
			NativeSlotLayout layout = new NativeSlotLayout(Map.of("g", 0), null);
			layout.freeze(List.of("g"));
			BindingSet base = EmptyBindingSet.getInstance();
			AggregateSpec countSpec = AggregateSpec.star("count");
			NativeGroupIteration emitter = new NativeGroupIteration(source, SlotPlan.singleton(), layout,
					new int[] { 0 }, new AggregateSpec[] { countSpec }, false, base, null, null, false, null);
			RowState row = new RowState(source, layout, base);
			assertThat(emitter.initialize(row)).isTrue();

			Aggregate terminal = new Aggregate(new int[] { 0 },
					new AggregateOutput[] { AggregateOutput.countStar() }, null, OutputMods.none());
			Kernel kernel = new Kernel(1, List.of(new EnumerateDomain(0, 0)), terminal);
			KernelGroupLayout groupLayout = new KernelGroupLayout(new int[] { 0 },
					new AggOut[] { new AggOut(countSpec, LmdbNativeKernelBindings.ENC_LONG_COUNT) });
			LmdbNativeKernelBindings bindings = new LmdbNativeKernelBindings(
					new LmdbNativeKernelBindings.AdjacencyRequest[0], new long[0], new int[0],
					new LmdbNativeKernelBindings.DomainRequest[0], new LmdbNativeKernelBindings.FilterHook[0],
					new int[] { 0 }, List.of(), groupLayout, true);
			LmdbNativeKernelLowering.Lowered lowered = new LmdbNativeKernelLowering.Lowered(kernel, bindings);
			BoundDomains domains = new BoundDomains(new long[][] { ids }, new int[] { 0 }, new int[] { ids.length });
			long parallelBefore = LmdbNativeParallelKernelAggregate.PARALLEL_RUNS.get();
			Function<Kernel, JaninoKernel> factory = requested -> {
				int invocation = factoryCalls.computeIfAbsent(Thread.currentThread(), ignored -> new AtomicInteger())
						.incrementAndGet();
				if (invocation == 2) {
					try {
						secondSegment.await(10, TimeUnit.SECONDS);
					} catch (InterruptedException e) {
						Thread.currentThread().interrupt();
						throw new AssertionError("interrupted at the second-segment retention checkpoint", e);
					} catch (BrokenBarrierException | TimeoutException e) {
						throw new AssertionError("workers did not reach the second-segment retention checkpoint", e);
					}
				}
				return LmdbNativeKernelInterpreter.forAggregate(requested);
			};

			List<BindingSet> result = LmdbNativeParallelKernelAggregate.tryEvaluate(lowered,
					new NativeLmdbQuerySource.NativeAdjacency[0],
					LmdbNativeKernelBindings.VariablePredicateViews.NONE, null, null, domains, SlotPlan.singleton(),
					row,
					emitter, null, factory, workers);

			List<BindingSet> expected = new ArrayList<>(ids.length);
			for (Value term : terms) {
				MapBindingSet expectedRow = new MapBindingSet();
				expectedRow.addBinding("g", term);
				expectedRow.addBinding("count", SimpleValueFactory.getInstance().createLiteral(BigInteger.ONE));
				expected.add(expectedRow);
			}
			assertThat(result).containsExactlyInAnyOrderElementsOf(expected);
			assertThat(LmdbNativeParallelKernelAggregate.PARALLEL_RUNS.get())
					.as("the noncanonical grouped domain must actually cross the parallel merge")
					.isGreaterThan(parallelBefore);
			int workersAtSecondSegment = 0;
			for (AtomicInteger calls : factoryCalls.values()) {
				if (calls.get() >= 2) {
					workersAtSecondSegment++;
				}
			}
			assertThat(workersAtSecondSegment).as("both source-bound workers must start a second segment").isEqualTo(2);
			// Each worker has completed one non-empty root window before its second factory call. Charge only one
			// UTF-16 lexical payload per worker here; this deliberately independent lower bound remains valid if the
			// scheduler changes its window sizing.
			long minimumKeyPayload = terms.stream()
					.mapToLong(value -> value.stringValue().length())
					.min()
					.orElseThrow() * 2L * Character.BYTES;
			assertThat(retainedAtSecondSegment.get())
					.as("noncanonical group-key Values must remain budget-owned after first hooks close")
					.isGreaterThan(minimumKeyPayload);
			assertThat(manager.usedBytes()).isZero();
		} finally {
			workers.shutdownNow();
			source.executionContext().close();
			LmdbNativeHashJoin.queryMemoryOverride = null;
		}
	}

	@Test
	void sameMorselDuplicateRdfTermTiesDoNotTriggerEncounterOrderFallback() {
		LmdbNativeRowDetachmentTest.FakeStoreSource values = new LmdbNativeRowDetachmentTest.FakeStoreSource();
		long first = values.add(SimpleValueFactory.getInstance().createLiteral("same", "en"));
		long duplicate = values.add(SimpleValueFactory.getInstance().createLiteral("same", "en"));
		SyntheticValueSource source = new SyntheticValueSource(new DuplicateTermSource(values), PlanValueCatalog.EMPTY)
				.forEvaluation();
		NativeSlotLayout layout = new NativeSlotLayout(Map.of(), null);
		layout.freeze(List.of());
		RowState row = new RowState(source, layout, EmptyBindingSet.getInstance());
		LmdbNativeKernelHooks hooks = extremaHooks(row);
		try {
			assertThat(first).isNotEqualTo(duplicate);
			assertThat(hooks.sameRdfTerm(first, duplicate)).isTrue();
			assertThat(hooks.compareValues(first, duplicate)).isZero();
			assertThat(hooks.replacesWinner(duplicate, first, true))
					.as("a duplicate RDF term must retain the existing MIN representative")
					.isFalse();
			assertThat(hooks.replacesWinner(duplicate, first, false))
					.as("a duplicate RDF term must retain the existing MAX representative")
					.isFalse();
		} finally {
			try {
				hooks.closeFilters();
			} finally {
				row.closeDecodedInputs();
				source.executionContext().close();
			}
		}
	}

	@Test
	void distinctRdfTermsWithEqualValueOrderingStillTriggerEncounterOrderFallback() {
		LmdbNativeRowDetachmentTest.FakeStoreSource values = new LmdbNativeRowDetachmentTest.FakeStoreSource();
		long integer = values.add(SimpleValueFactory.getInstance().createLiteral("1", CoreDatatype.XSD.INTEGER));
		long decimal = values.add(SimpleValueFactory.getInstance().createLiteral("1.0", CoreDatatype.XSD.DECIMAL));
		SyntheticValueSource source = new SyntheticValueSource(new DuplicateTermSource(values), PlanValueCatalog.EMPTY)
				.forEvaluation();
		NativeSlotLayout layout = new NativeSlotLayout(Map.of(), null);
		layout.freeze(List.of());
		RowState row = new RowState(source, layout, EmptyBindingSet.getInstance());
		LmdbNativeKernelHooks hooks = extremaHooks(row);
		try {
			assertThat(integer).isNotEqualTo(decimal);
			assertThat(hooks.sameRdfTerm(integer, decimal)).isFalse();
			assertThat(hooks.compareValues(integer, decimal)).isZero();
			assertThatThrownBy(() -> hooks.replacesWinner(decimal, integer, true))
					.isInstanceOf(EncounterOrderFallback.class);
			assertThatThrownBy(() -> hooks.replacesWinner(decimal, integer, false))
					.isInstanceOf(EncounterOrderFallback.class);
		} finally {
			try {
				hooks.closeFilters();
			} finally {
				row.closeDecodedInputs();
				source.executionContext().close();
			}
		}
	}

	@Test
	void workerFilterOwnershipSurvivesMultipleMorsels() {
		LmdbNativeRowDetachmentTest.FakeStoreSource values = new LmdbNativeRowDetachmentTest.FakeStoreSource();
		DuplicateTermSource delegate = new DuplicateTermSource(values);
		SyntheticValueSource source = new SyntheticValueSource(delegate, PlanValueCatalog.EMPTY).forEvaluation();
		List<TrackingFilter> workerFilters = new CopyOnWriteArrayList<>();
		AtomicInteger activeLeases = new AtomicInteger();
		TrackingFilter filter = new TrackingFilter(workerFilters, activeLeases);

		try {
			NativeSlotLayout layout = new NativeSlotLayout(Map.of("v", 0), null);
			layout.freeze(List.of("v"));
			BindingSet base = EmptyBindingSet.getInstance();
			NativeGroupIteration emitter = new NativeGroupIteration(source, SlotPlan.singleton(), layout, new int[0],
					new AggregateSpec[] { AggregateSpec.star("count") }, false, base, null, null, false, null);
			RowState row = new RowState(source, layout, base);
			assertThat(emitter.initialize(row)).isTrue();

			AggregateOutput output = AggregateOutput.countStar();
			Aggregate terminal = new Aggregate(new int[0], new AggregateOutput[] { output }, null, OutputMods.none());
			Kernel kernel = new Kernel(1,
					List.of(new EnumerateDomain(0, 0),
							new LmdbNativeKernelIr.FilterValue(0,
									new LmdbNativeKernelIr.Operand[] { LmdbNativeKernelIr.Operand.col(0) }, true)),
					terminal);
			KernelGroupLayout groupLayout = new KernelGroupLayout(new int[0],
					new AggOut[] { new AggOut(emitter.aggregates[0], LmdbNativeKernelBindings.ENC_LONG_COUNT) });
			LmdbNativeKernelBindings.FilterHook[] filterHooks = {
					new LmdbNativeKernelBindings.FilterHook(new MaskedFilter(filter, 1L),
							new int[] { 0 }) };
			LmdbNativeKernelBindings bindings = new LmdbNativeKernelBindings(
					new LmdbNativeKernelBindings.AdjacencyRequest[0], new long[0], new int[0],
					new LmdbNativeKernelBindings.DomainRequest[0], filterHooks, new int[0], List.of(), groupLayout,
					true);
			LmdbNativeKernelLowering.Lowered lowered = new LmdbNativeKernelLowering.Lowered(kernel, bindings);
			long[] ids = new long[2_048];
			for (int i = 0; i < ids.length; i++) {
				ids[i] = 10L + i;
			}
			BoundDomains domains = new BoundDomains(new long[][] { ids }, new int[] { 0 }, new int[] { ids.length });
			long parallelBefore = LmdbNativeParallelKernelAggregate.PARALLEL_RUNS.get();
			ExecutorService workers = Executors.newFixedThreadPool(2);
			try {
				List<BindingSet> result = LmdbNativeParallelKernelAggregate.tryEvaluate(lowered,
						new NativeLmdbQuerySource.NativeAdjacency[0],
						LmdbNativeKernelBindings.VariablePredicateViews.NONE, null, null, domains, SlotPlan.singleton(),
						row,
						emitter, null, LmdbNativeKernelInterpreter::forAggregate, workers);

				assertThat(result).hasSize(1);
				assertThat(result.get(0).getValue("count").stringValue()).isEqualTo("2048");
				assertThat(LmdbNativeParallelKernelAggregate.PARALLEL_RUNS.get()).isGreaterThan(parallelBefore);
				assertThat(workerFilters).hasSize(2);
				for (TrackingFilter workerFilter : workerFilters) {
					assertThat(workerFilter.closeCalls()).as("worker filter close count").isEqualTo(1);
					assertThat(workerFilter.leaseOpens()).as("worker filter lease open count").isEqualTo(1);
					assertThat(workerFilter.leaseOpen()).as("worker filter lease released").isFalse();
				}
				assertThat(activeLeases).as("all worker filter leases released").hasValue(0);
			} finally {
				workers.shutdownNow();
			}
		} finally {
			source.executionContext().close();
		}
	}

	private static LmdbNativeKernelHooks extremaHooks(RowState row) {
		AggregateSpec spec = AggregateSpec.slot("extreme", 0, false, AggKind.MIN);
		KernelGroupLayout groupLayout = new KernelGroupLayout(new int[0],
				new AggOut[] { new AggOut(spec, LmdbNativeKernelBindings.ENC_VALUE_ID) });
		LmdbNativeKernelBindings bindings = new LmdbNativeKernelBindings(
				new LmdbNativeKernelBindings.AdjacencyRequest[0], new long[0], new int[0],
				new LmdbNativeKernelBindings.DomainRequest[0], new LmdbNativeKernelBindings.FilterHook[0], new int[0],
				List.of(), groupLayout, true);
		return new LmdbNativeKernelHooks(row, bindings);
	}

	private static final class TrackingFilter implements NativeBooleanFilter {
		private final List<TrackingFilter> workers;
		private final AtomicInteger activeLeases;
		private final AtomicInteger closeCalls = new AtomicInteger();
		private final AtomicInteger leaseOpens = new AtomicInteger();
		private final AtomicBoolean leaseOpen = new AtomicBoolean();

		private TrackingFilter(List<TrackingFilter> workers, AtomicInteger activeLeases) {
			this.workers = workers;
			this.activeLeases = activeLeases;
		}

		@Override
		public boolean accept(RowState row) {
			if (leaseOpen.compareAndSet(false, true)) {
				activeLeases.incrementAndGet();
				leaseOpens.incrementAndGet();
			}
			return true;
		}

		@Override
		public boolean parallelWorkerForkable() {
			return true;
		}

		@Override
		public NativeBooleanFilter forkForParallelWorker(NativeScalarPlan.WorkerContext context) {
			TrackingFilter worker = new TrackingFilter(workers, activeLeases);
			workers.add(worker);
			return worker;
		}

		@Override
		public void close() {
			closeCalls.incrementAndGet();
			if (leaseOpen.compareAndSet(true, false)) {
				activeLeases.decrementAndGet();
			}
		}

		private int closeCalls() {
			return closeCalls.get();
		}

		private int leaseOpens() {
			return leaseOpens.get();
		}

		private boolean leaseOpen() {
			return leaseOpen.get();
		}
	}

	private static final class DuplicateTermSource implements NativeLmdbQuerySource.ParallelSource {
		private final LmdbNativeRowDetachmentTest.FakeStoreSource values;
		private final Object idSpace;

		private DuplicateTermSource(LmdbNativeRowDetachmentTest.FakeStoreSource values) {
			this(values, new Object());
		}

		private DuplicateTermSource(LmdbNativeRowDetachmentTest.FakeStoreSource values, Object idSpace) {
			this.values = values;
			this.idSpace = idSpace;
		}

		@Override
		public NativeLmdbQuerySource.ParallelSource[] openParallelSources(int count) {
			NativeLmdbQuerySource.ParallelSource[] siblings = new NativeLmdbQuerySource.ParallelSource[count];
			for (int i = 0; i < count; i++) {
				siblings[i] = new DuplicateTermSource(values, idSpace);
			}
			return siblings;
		}

		@Override
		public long idOf(Value value) {
			return values.idOf(value);
		}

		@Override
		public Value lazyValue(long id) {
			return values.lazyValue(id);
		}

		@Override
		public Object idSpace() {
			return idSpace;
		}

		@Override
		public boolean hasCanonicalIds() {
			return false;
		}

		@Override
		public RecordIterator statements(long subj, long pred, long obj, long context) {
			return SyntheticValueSource.EMPTY;
		}

		@Override
		public long count(long subj, long pred, long obj, long context) {
			return 0L;
		}

		@Override
		public boolean has(long subj, long pred, long obj, long context) {
			return false;
		}

		@Override
		public double estimate(long subj, long pred, long obj, long context) {
			return 0D;
		}

		@Override
		public boolean hasStatementsInSource() {
			return true;
		}

		@Override
		public void close() {
		}
	}
